) AS (
  VALUES 
    (56::BIGINT, 'Excelente profesor. Siempre está dispuesto a ayudar, muchas veces fuera del tiempo lectivo nos explicaba temas que tal vez no nos habían quedado tan claros. Hay que estar bien atento a la parte de excel ya que es la parte más complicada del curso y es el examen que más porcentaje tiene.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'b9eb52ab4dbabc23c0e778f5ef6ebb64bb0b1618d620375e9952ab2ba8d96210'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Siempre tuvo cierta actitud con una compañera entonces era incomodo. Clases largas pero da receso de 20 minutos. La mayoria las dejó grabadas. El curso comienza muy basica y en la parte de excel no tanto, entonces si le cuesta mucho si repase antes del examen de excel que es el que más nota vale.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'ef31cca955ffdf169617bb7fcd3f8ee673a8228221938b09d8fff6e17a0ea17f'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Excelente profesor, es una teja de persona, explica muy bien y ayudaa que todos entiendan. Si no sabe mucho de Excel (o no sabe nada), es el mejor profe. Lo super recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'e053f9b82027b0e755ec6fed1eef9ab5eb32639db03d91eff8a062e922dbe5e2'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Muy buen profe, vaya preparado para aprender mucho en excel y ponga mucha atención pq hay veces que va rápido. Si hace preguntas él le responde bien, a veces regala chocolates o confites. Las clases son divertidas, pero de poner mucha atención'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, '2b463c0bf84ee6118fbf9142dc053984d23e829cf224d6f994b10cdee48f3190'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Pienso que fue un muy buen profesor, lo recomiendo bastante. Si sabe poco o nada de Excel, ponga muchísima atención y no falte a ninguna clase, ya que en 4 horas el profe ve infinidad de temas. Si ocupa ayuda, el profe le ayudará con gusto. Sus exámenes y proyectos son largos, pero se aprende mucho.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'af592b10fe215dee89640d98e99f8be19b55baa3c6d185c9ab382f2dc0deb11f'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, '84d6daef6c9e915faa6699ad30666d90bec262af3d46004594a03d4e19be9112'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Es super buen profesor, explica con paciencia y se nota que le gusta lo que hace. Lo único es que para S18 solo se ha publicado el 25% del curso, a veces queda uno a la espera de que suba instrucciones y no las sube, y entonces después hay menos tiempo para hacer los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2fb15a8b326f2b16f8b542a2de6f21841f42d9254f20e2325e439e2415685c06'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'El profe sabe bastante, da retroalimentación cuando se la piden, pero es muy desorganizado, no tiene claridad en lo que quiere, corre las fechas programadas para cuando quiere, entonces eso hace que el curso sea un poco estresante y da incertidumbre.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-01-17T00:00:00+00:00'::TIMESTAMPTZ, '73fe6c1ee0baf054128f0be03f09652e2fe9b7eb2cf8da0bd4ca7e2da35fb757'::TEXT, ARRAY[2399]::BIGINT[]),
    (56::BIGINT, 'El profe puede ser muy organizado con unas cosas peor muy desordenado con otras, a veces le toca correr fechas y demás. sus clases son largas, es algo charlatán entonces le gusta que participen en clase y regala chocolates. Puede hacer que el cursos se vuelva más teórico que práctico.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2023-10-26T00:00:00+00:00'::TIMESTAMPTZ, 'e554ee09cb319e1222a8086964daeb6b64bb1717bcf1fb3fbf742af2362a5c10'::TEXT, ARRAY[2399]::BIGINT[]),
    (56::BIGINT, 'Es buen profe, hace bromas que pueden ser un poco bruscas, pero es para intentar relajar a la clase. Las fechas de entrega a veces pueden ser confusas, pero siempre da tiempo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '91eee6d31e4c6aeba5e512d3fb0fcd7dcc5a13fdf1a4bd98d94eb3f3e1e3d87d'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'El profe es muy buena gente. Explica súper claro y le ayuda las veces que sea necesario en caso de que no entienda. Las tareas que deja son fáciles, los proyectos son largos pero fáciles de hacer con su grupo. A veces no hay claridad con las fechas de entrega. Lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '7b31c13e6885984e3de1ed63813e1cc12d5c78506e51bd5da55b40c81ab9e3ff'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'No es claro con las fechas, uno se da cuenta de las cosas el día antes y por alguien más. Es demasiado exigente con los exámenes y da poco tiempo, a veces ni se puede terminar. Los trabajos son grupales y bastante largos, pero al igual que las clases, son muy fáciles'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '49574b1ada66c0ffc5292a9ff1d725d906ffee8931cc739e514950231a0e9778'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Super buen profe. Las clases son largas pero si tenés una duda el se detiene a explicarte. Los examenes son practicamente la practica de examen que pone una semana antes. Hay tareas y proyectos grupales un poco largas pero deja mucho tiempo para hacerlas. Siempre abarca dudas por privado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e95cab97f5bc5aaeed07ba0ec59f16175f31c8988a22c56178bfa140dc429e97'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Los proyectos son largos pero, al igual que los exámenes, es similar a las practicas que se hacen en clase. Es muy comprensivo y pasar el curso con él es fácil y muy practico'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, '0c839ae9604e3c7afce57dfb0b94b2f796e269b4c87794070b6e3c564a67ee1c'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'El profe es amable, ayuda mucho y grava las clases lo cual es muy bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'd7aa221acd973f46ee20f66c71223f1b70500dfaad9788f9ab4e861cd2dbb10a'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Es un acosador el viejo verde'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '0c0721d8a4d07a46e0632b9ac469565f28bc269f8e7522ce999c20c853f01823'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Es un buen profesor. Atento al estudiante y es muy buena persona. Sus trabajos pueden ser algo largos, pero si los hacen con tiempo y dedicación, todo bien. Los exámenes no son difíciles y son muy similares a las prácticas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'e362b4c544c1b41ea7d226c4981dbf6f92eae5884ce94fa6ccab0f8ff2d5aa3b'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'bcf5456148da05a10fb256df6aedaed7cb80271148bf132b5d16013c51ec6b64'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Vas a aprender de verdad, pero obviamente debes practicar muy bien para antes de las pruebas, intenta no faltar a las clases, ya que son muy esenciales, no dejes nada para ultima hora e intenta tener una muy buena comunicación con tus compañeros de trabajo en los avances de los proyectos grupales.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2021-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'ab409cd0d71af7ef79060ad483a7d7766cb8dfce8389c6e0e9b326fb801bfaba'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Las clases son pesadas, pero si se entienden. Son 4 únicos exámenes pero si son bastante largos. Así como sus prácticas. En general no deja tareas, ya que todo lo debes ir haciendo en clase. Siento que no califica duro. Sólo que la materia no lo hace ser más flexible, ya que a veces se torna aburrid'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '96e6e7408a4f81e0c863fe7f4be460d0f2f2091b293f1621ac6bf31fda878536'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Podría decir que es el mejor profe con el que he recibido clases. Las clases las hace entretenidas, la materia es compleja pero él la hace ver sencilla. Explica todo paso a paso, si ponen atención a la clase y hacen sus apuntes les irá genial.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8eddf98beb7269f14c574fb5d85d4785419104dacbf599ef16eebea0c3b11349'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'El curso cuenta de varios exámenes lo cuales son un poco largos pero si pusiste atención a las clases y prácticas te va genial! Es el mejor profe hasta el momento, explica muy bien y ayuda muchísimo, sus clases son largas pero no aburridas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '8c883792823ce03b7168ee5059563c381fa8b1c11483232b3063ec8871f5e381'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Es un excelente profe, el curso por si solo es muy aburrido, pero él hace lo mejor que puede. Siempre atento y explica las cosas paso a paso con mucha paciencia. Sin embargo, los trabajos que deja son bastante largos y los exámenes son difíciles.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-05-11T00:00:00+00:00'::TIMESTAMPTZ, '1b577034663fe1ddc07dff03b67666c1773076f77184a74d61e290bea169298e'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'De los mejores profesores Siempre atento, si necesita ayudar en horas extra lo hace, siempre con buen carácter y humor Excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '366cee3f1ea9baa0f9829317b4ff54674f7b3449194efceb1cd428a1f9a63a92'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '1bbb51a05f1ede2fafc86464a0a69b3d4df2bae9550c94346ab6219518a7a2bc'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Cae demasiado bien. Explica muy bien y ayuda al que lo necesite. Creo que no hay mejor profesor para está materia. Los exámenes son muy fáciles, las tareas también y el proyecto es entretenido y fácil. Respeta al estudiante, es cómico, muy buena persona, da un receso y es una excelente persona.100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'a3252d8395afa280d9e179b2507592a7f094f2728e7c7b32a00727023bd7a245'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'El profe es muy buena gente pero califica muy duro y los exámenes son un poco difícil pero el brinda mucha ayuda, pero matriculen con el es el mejor profe de compu para admi'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '0f1bd26d3fa005b56bffceef0ca40f2a5d2768bf964acd7aab9fefc7640628b7'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Es un profe bueno aunque algo aburridillo. No lo culpo, la materia en sí lo es. Explica paso por paso y brinda apoyo a quien lo necesite. De lo que he escuchado, es el mejor profesor que hay en esta materia... Sus trabajos son MUY LARGOS, entonces hacerlos con antelación.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, '76aec02a4a531d74609062d13f999e06b4e7953851532adaae3c485685302391'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Muy buen profe Se aprende bastante, no aburre y califica suave Si puede meter con el, no lo dude'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'ecdab92b275339edb6d254fcf5eb3b06211607431671aa3f2077436d21dc58b6'::TEXT, ARRAY[2399]::BIGINT[]),
    (56::BIGINT, 'Es buena gente, no es aburrido y explica bien. Hace examenes un poco rudo y hay que ponerle un poco más que con los otros profes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'dfb80a0b32fa52853a8b36e3f894222a7f50fdaf9061d8827c3755ebcfded7f9'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Explica bien pero rápido, no se confien'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0cea769ff04f665ad727d655f29b1dd7b79f87c1d9858d50c702e41f57cd418d'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Es un poco grosero y la clase es medio aburrida pero creo que es mejor que los otros profes de compu para admi. Los exámenes son un poco difíciles pero él revisa suave entonces a la gente le va bien.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'c71c91a9418e837dd4529dafa37a7cbd9f46f31e1f8cf8ac0cdbbbb47c3ee5b9'::TEXT, ARRAY[2376]::BIGINT[]),
    (56::BIGINT, 'Es fácil pero enseña mas de lo que se necesita.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd8050955eebb15f9663b9fd025ac8b08fe3bbc314294e7a0fead9ebfe37d9b1d'::TEXT, ARRAY[2376]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
